ider_user_id',l.source_provider_user_id,'source_provider_recorded',CAST(l.source_provider_recorded AS UNSIGNED),'provider_owner_type',l.provider_owner_type,'provider_owner_id',l.provider_owner_id,'provider_owner_name_snapshot',l.provider_owner_name_snapshot,'contribution_user_id_snapshot',l.contribution_user_id_snapshot,'contribution_user_name_snapshot',l.contribution_user_name_snapshot,'contribution_supervisor_user_id_snapshot',l.contribution_supervisor_user_id_snapshot,'contribution_supervisor_name_snapshot',l.contribution_supervisor_name_snapshot,'contribution_dept_id_snapshot',l.contribution_dept_id_snapshot,'contribution_dept_name_snapshot',l.contribution_dept_name_snapshot,'counted_at',DATE_FORMAT(l.counted_at,'%Y-%m-%d %H:%i:%s'),'version',l.version,'updater',l.updater,'update_time',DATE_FORMAT(l.update_time,'%Y-%m-%d %H:%i:%s')),JSON_OBJECT('source',IF(m.kind='partner','zsjos_partner.name at repair time; not original historical name','user-confirmed unassisted self-sourcing'),'provider_id',m.provider_id,'approved_on','2026-10-10','captured_at',DATE_FORMAT(v_now,'%Y-%m-%d %H:%i:%s')) FROM zsjos_lead l JOIN v307_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1;
 INSERT INTO zsjos_data_repair_backup(repair_key,table_name,row_id,column_name,old_value) SELECT 'lead-provider-v307','zsjos_lead',i.row_id,'__before__',CAST(i.before_image AS CHAR CHARACTER SET utf8mb4) FROM v307_images i WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='lead-provider-v307' AND b.row_id=i.row_id AND b.table_name='zsjos_lead' AND b.column_name='__before__');
 INSERT INTO zsjos_data_repair_backup(repair_key,table_name,row_id,column_name,old_value) SELECT 'lead-provider-v307','zsjos_lead',i.row_id,'__after__',CAST(i.after_image AS CHAR CHARACTER SET utf8mb4) FROM v307_images i WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='lead-provider-v307' AND b.row_id=i.row_id AND b.table_name='zsjos_lead' AND b.column_name='__after__');
 INSERT INTO zsjos_data_repair_backup(repair_key,table_name,row_id,column_name,old_value) SELECT 'lead-provider-v307','zsjos_lead',i.row_id,'__provenance__',CAST(i.provenance AS CHAR CHARACTER SET utf8mb4) FROM v307_images i WHERE NOT EXISTS(SELECT 1 FROM zsjos_data_repair_backup b WHERE b.repair_key='lead-provider-v307' AND b.row_id=i.row_id AND b.table_name='zsjos_lead' AND b.column_name='__provenance__');
