-- UTF-8. V307, tenant 1 only, exact reviewed manifest: 492 Partner names + 4 self-sourced corrections.
-- Requires V306 and existing InnoDB LONGTEXT zsjos_data_repair_backup; run after V306.
-- User explicitly approved current Partner names as repair-time labels, NOT proven original historical labels.
-- Provenance and original/expected images are retained under lead-provider-v307 in the repair backup.
-- Names/IDs outside this manifest and all permissions, orders, money, BPM and historical messages remain unchanged.
-- Four self-sourced rows: remove erroneous system_user provider, record explicit unassisted sourcing.
-- No source_user/owner/organization/counting-time change; preflight rejects nonempty contribution facts.
-- Atomic DML and both success ledgers. Procedure DDL is not transactional. Client MUST stop on SQL error.
-- Repeat and partial recovery use recorded images even if success ledgers already exist; later edits reject.
-- Fresh empty environments are a no-op with version registration. Partial manifest presence is rejected.
-- Rollback requires reviewed exact after-image match before restoring before-images; preserve provenance.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP PROCEDURE IF EXISTS zsjos_v307_apply;
DELIMITER $$
CREATE PROCEDURE zsjos_v307_apply()
BEGIN
 DECLARE v_now DATETIME DEFAULT NOW();
 DECLARE v_count INT;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF NOT EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V306') OR NOT EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V306') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 requires V306 in both ledgers';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_data_repair_backup' AND column_name='old_value' AND data_type='longtext') THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 requires LONGTEXT backup';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('zsjos_lead','zsjos_partner','zsjos_data_repair_backup','zsjos_schema_version','zsjos_module_schema_version') AND engine='InnoDB')<>5 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 requires transactional tables';
 END IF;
 DROP TEMPORARY TABLE IF EXISTS v307_manifest;
 CREATE TEMPORARY TABLE v307_manifest(lead_no VARCHAR(64) PRIMARY KEY,provider_id BIGINT NOT NULL,kind VARCHAR(16) NOT NULL,source_type VARCHAR(32)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
 SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
 START TRANSACTION;
 SELECT COUNT(*) INTO v_count FROM zsjos_lead l JOIN v307_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 FOR UPDATE;
 IF v_count NOT IN (0,496) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 partial manifest; review deployment data'; END IF;
 IF v_count=496 AND (EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V307') OR EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V307')) AND (SELECT COUNT(*) FROM zsjos_data_repair_backup WHERE repair_key='lead-provider-v307')<>1488 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 ledger without complete repair evidence';
 END IF;
 IF EXISTS(SELECT 1 FROM zsjos_lead l JOIN v307_manifest m ON m.lead_no=l.lead_no WHERE l.tenant_id=1 AND (l.deleted<>0 OR (m.kind='partner' AND (NOT(l.provider_owner_type <=> 'partner') OR NOT(l.provider_owner_id <=> m.provider_id))) OR (m.kind='self' AND (NOT(l.source_type <=> m.source_type) OR NOT(l.source_user_id <=> m.provider_id) OR l.source_provider_user_id IS NOT NULL OR l.contribution_user_id_snapshot IS NOT NULL OR l.contribution_user_name_snapshot IS NOT NULL OR l.contribution_supervisor_user_id_snapshot IS NOT NULL OR l.contribution_supervisor_name_snapshot IS NOT NULL OR l.contribution_dept_id_snapshot IS NOT NULL OR l.contribution_dept_name_snapshot IS NOT NULL)))) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 manifest identity or contribution changed';
 END IF;
 IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup WHERE repair_key='lead-provider-v307' GROUP BY table_name,row_id,column_name HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 duplicate backup'; END IF;
 IF EXISTS(SELECT 1 FROM zsjos_data_repair_backup b LEFT JOIN zsjos_lead l ON l.id=b.row_id AND l.tenant_id=1 LEFT JOIN v307_manifest m ON m.lead_no=l.lead_no WHERE b.repair_key='lead-provider-v307' AND (m.lead_no IS NULL OR b.table_name<>'zsjos_lead')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 backup target missing'; END IF;
 DROP TEMPORARY TABLE IF EXISTS v307_images;
 CREATE TEMPORARY TABLE v307_images(row_id BIGINT PRIMARY KEY,kind VARCHAR(16),before_image JSON,after_image JSON,current_image JSON,provenance JSON) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
 IF EXISTS(SELECT 1 FROM v307_images i JOIN zsjos_data_repair_backup b ON b.repair_key='lead-provider-v307' AND b.table_name='zsjos_lead' AND b.row_id=i.row_id WHERE (SELECT COUNT(*) FROM zsjos_data_repair_backup z WHERE z.repair_key=b.repair_key AND z.table_name=b.table_name AND z.row_id=b.row_id AND z.column_name IN ('__before__','__after__','__provenance__'))<>3) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 incomplete backup'; END IF;
 IF EXISTS(SELECT 1 FROM v307_images i LEFT JOIN zsjos_data_repair_backup b ON b.repair_key='lead-provider-v307' AND b.table_name='zsjos_lead' AND b.row_id=i.row_id WHERE b.id IS NULL AND (JSON_TYPE(i.before_image->'$.provider_owner_name_snapshot')<>'NULL' OR (i.kind='self' AND (NOT(i.before_image->>'$.provider_owner_type' <=> 'system_user') OR NOT(CAST(i.before_image->>'$.provider_owner_id' AS UNSIGNED) <=> CAST(i.provenance->>'$.provider_id' AS UNSIGNED)) OR NOT(i.before_image->>'$.source_provider_recorded' <=> '0'))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 original reviewed state changed'; END IF;
 IF EXISTS(SELECT 1 FROM v307_images i LEFT JOIN zsjos_data_repair_backup b ON b.repair_key='lead-provider-v307' AND b.table_name='zsjos_lead' AND b.row_id=i.row_id LEFT JOIN zsjos_partner p ON p.id=CAST(i.provenance->>'$.provider_id' AS UNSIGNED) AND p.tenant_id=1 AND p.deleted=0 WHERE i.kind='partner' AND b.id IS NULL AND (p.id IS NULL OR NULLIF(TRIM(p.name),'') IS NULL)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 partner name unavailable'; END IF;
 UPDATE v307_images i JOIN zsjos_partner p ON p.id=CAST(i.provenance->>'$.provider_id' AS UNSIGNED) AND p.tenant_id=1 SET i.after_image=JSON_SET(i.after_image,'$.provider_owner_name_snapshot',p.name) WHERE i.kind='partner';
 UPDATE v307_images SET after_image=JSON_SET(after_image,'$.provider_owner_type',NULL,'$.provider_owner_id',NULL,'$.provider_owner_name_snapshot',NULL,'$.source_provider_recorded',1) WHERE kind='self';
 UPDATE v307_images SET after_image=JSON_SET(after_image,'$.version',CAST(before_image->>'$.version' AS UNSIGNED)+1,'$.updater','lead-provider-v307','$.update_time',DATE_FORMAT(v_now,'%Y-%m-%d %H:%i:%s'));
 UPDATE v307_images i JOIN zsjos_data_repair_backup b ON b.repair_key='lead-provider-v307' AND b.table_name='zsjos_lead' AND b.row_id=i.row_id AND b.column_name='__before__' JOIN zsjos_data_repair_backup a ON a.repair_key=b.repair_key AND a.table_name=b.table_name AND a.row_id=b.row_id AND a.column_name='__after__' SET i.before_image=CAST(b.old_value AS JSON),i.after_image=CAST(a.old_value AS JSON);
 IF EXISTS(SELECT 1 FROM v307_images WHERE NOT(current_image=before_image OR current_image=after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 later edits conflict; refusing overwrite'; END IF;
 UPDATE zsjos_lead l JOIN v307_images i ON i.row_id=l.id SET l.provider_owner_type=NULLIF(i.after_image->>'$.provider_owner_type','null'),l.provider_owner_id=CAST(NULLIF(i.after_image->>'$.provider_owner_id','null') AS UNSIGNED),l.provider_owner_name_snapshot=IF(JSON_TYPE(i.after_image->'$.provider_owner_name_snapshot')='NULL',NULL,i.after_image->>'$.provider_owner_name_snapshot'),l.source_provider_recorded=CAST(NULLIF(i.after_image->>'$.source_provider_recorded','null') AS UNSIGNED),l.version=CAST(i.after_image->>'$.version' AS UNSIGNED),l.updater=i.after_image->>'$.updater',l.update_time=i.after_image->>'$.update_time' WHERE i.current_image<>i.after_image;
 IF EXISTS(SELECT 1 FROM zsjos_lead l JOIN v307_images i ON i.row_id=l.id WHERE NOT(JSON_OBJECT('source_type',l.source_type,'source_user_id',l.source_user_id,'source_provider_user_id',l.source_provider_user_id,'source_provider_recorded',CAST(l.source_provider_recorded AS UNSIGNED),'provider_owner_type',l.provider_owner_type,'provider_owner_id',l.provider_owner_id,'provider_owner_name_snapshot',l.provider_owner_name_snapshot,'contribution_user_id_snapshot',l.contribution_user_id_snapshot,'contribution_user_name_snapshot',l.contribution_user_name_snapshot,'contribution_supervisor_user_id_snapshot',l.contribution_supervisor_user_id_snapshot,'contribution_supervisor_name_snapshot',l.contribution_supervisor_name_snapshot,'contribution_dept_id_snapshot',l.contribution_dept_id_snapshot,'contribution_dept_name_snapshot',l.contribution_dept_name_snapshot,'counted_at',DATE_FORMAT(l.counted_at,'%Y-%m-%d %H:%i:%s'),'version',l.version,'updater',l.updater,'update_time',DATE_FORMAT(l.update_time,'%Y-%m-%d %H:%i:%s'))=i.after_image)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V307 postcondition failed'; END IF;
 COMMIT;
END$$
DELIMITER ;
CALL zsjos_v307_apply();
DROP PROCEDURE zsjos_v307_apply;
